-- @marker SEED-10-17
-- 대상 IT-10-086 IT-10-087
-- 입찰 분석 PDF 다운로드 장면. 분석 완료 본문은 seed/10-12 와 같다(Pwin 72.0, Strong Go)
-- 1번은 요구 문장 한글이 붙은 컴플라이언스 매트릭스를 가진 공개 공고에 건 분석 완료 건이고 관리자 결정이 조건부 Go 다.
-- 요구 항목 칸에 그 공고의 REQ ID 셋을 넣어 화면은 접고 인쇄는 펼치는지 본다. 맞는 공고가 없으면 입찰 건이 생기지 않아 재료 없음이 된다. 공고는 지우지 않는다
-- 2번은 결정만 기록한 회차(A), 3번은 회차가 없는 분석 단계 건(C), 4번은 종합 분석 리포트만 저장된 분석 중 회차(B)다
-- 분석 중 회차는 워크플로우 대기 한도(10/25 상용 60분) 안이어야 하므로 키는 50분 안에 시작한 것만 준다. 대기 한도를 50분 아래로 줄이면 이 창도 줄인다
-- @key 10.b086_virtual_bid SELECT '[[uuid:03:1]]' AS id, HEX(id) AS hex FROM bid_requests WHERE id = [[id:03:1]] AND state = 'ANALYZING' AND EXISTS (SELECT 1 FROM bid_analyses ba WHERE ba.id = [[id:0c:1]] AND ba.admin_decision = 'CONDITIONAL_GO')
-- @key 10.b087_a_bid SELECT '[[uuid:03:2]]' AS id, HEX(id) AS hex FROM bid_requests WHERE id = [[id:03:2]] AND state = 'ANALYZING'
-- @key 10.b087_c_bid SELECT '[[uuid:03:3]]' AS id, HEX(id) AS hex FROM bid_requests WHERE id = [[id:03:3]] AND state = 'ANALYZING' AND NOT EXISTS (SELECT 1 FROM bid_analyses ba WHERE ba.bid_request_id = [[id:03:3]])
-- @key 10.b087_b_bid SELECT '[[uuid:03:4]]' AS id, HEX(id) AS hex FROM bid_requests WHERE id = [[id:03:4]] AND state = 'ANALYZING' AND EXISTS (SELECT 1 FROM bid_analyses ba WHERE ba.id = [[id:0c:4]] AND ba.status = 'RUNNING' AND ba.started_at >= [[now]] - INTERVAL 50 MINUTE)
