INSERT INTO bid_requests (id, member_id, opportunity_id, state, state_history, service_level, created_at, updated_at)
SELECT [[id:03:1]], [[id:01:1]], x.id, 'ANALYZING', JSON_ARRAY(JSON_OBJECT('fromState', 'DOCS_RECEIVED', 'toState', 'ANALYZING', 'userId', NULL, 'username', 'seed', 'timestamp', JSON_ARRAY(YEAR([[now]] - INTERVAL 3 HOUR), MONTH([[now]] - INTERVAL 3 HOUR), DAY([[now]] - INTERVAL 3 HOUR), HOUR([[now]] - INTERVAL 3 HOUR), MINUTE([[now]] - INTERVAL 3 HOUR), SECOND([[now]] - INTERVAL 3 HOUR), 0), 'notes', '시딩', 'automatic', FALSE)), 'FULL_PACKAGE', [[now]], [[now]] FROM (SELECT o.id FROM opportunities o JOIN notices n ON n.opportunity_id = o.id AND n.generation_status = 'COMPLETED' AND n.visibility = 'VISIBLE' WHERE o.deleted_at IS NULL AND (SELECT COUNT(*) FROM opportunity_requirement_items r WHERE r.opportunity_id = o.id AND r.req_id IS NOT NULL AND JSON_VALUE(r.requirement_json, '$.translation') IS NOT NULL) >= 3 ORDER BY o.updated_at DESC LIMIT 1) x;
