SET @req3 := (SELECT r.req_id FROM opportunity_requirement_items r JOIN bid_requests br ON br.opportunity_id = r.opportunity_id WHERE br.id = [[id:03:1]] AND r.req_id IS NOT NULL AND JSON_VALUE(r.requirement_json, '$.translation') IS NOT NULL ORDER BY r.sort_order, r.req_id LIMIT 1 OFFSET 2);
